// 对同一批语料算确定性契约指标；与 Quality_Monitor 用的是同一套判据
const TAGS = ['AI', '安全', '硬件', '开发', '商业', '生态'];
const SENTIMENTS = ['Positive', 'Negative', 'Neutral'];
const END_PUNCT = '。！？';
const BLOCKED = 'Analysis failed due to content access issues.';

const corpus = $('Load_Eval_Corpus').all().map((r) => r.json);
const responses = $input.all().map((r) => r.json);
if (corpus.length !== responses.length) {
  throw new Error('语料 ' + corpus.length + ' 条与响应 ' + responses.length + ' 条不对齐，无法配对打分');
}

const bySource = {};
const totals = { n: 0, unparseable: 0, tag_invalid: 0, too_long: 0,
                 no_end_punct: 0, ascii_quote: 0, sentiment_invalid: 0, blocked: 0 };

const bump = (bucket, key) => { bucket[key] = (bucket[key] || 0) + 1; };

for (let i = 0; i < corpus.length; i++) {
  const sourceKey = corpus[i].source_key || 'unknown';
  if (!bySource[sourceKey]) {
    bySource[sourceKey] = { n: 0, unparseable: 0, tag_invalid: 0, too_long: 0,
                            no_end_punct: 0, ascii_quote: 0, sentiment_invalid: 0, blocked: 0 };
  }
  const bucket = bySource[sourceKey];
  bump(bucket, 'n'); totals.n += 1;

  const raw = responses[i] && responses[i].choices && responses[i].choices[0]
    && responses[i].choices[0].message ? responses[i].choices[0].message.content : null;

  let parsed = null;
  if (typeof raw === 'string') {
    const stripped = raw.split('```json').join('').split('```').join('').trim();
    try { parsed = JSON.parse(stripped); } catch (e) { parsed = null; }
  }
  if (!parsed) { bump(bucket, 'unparseable'); totals.unparseable += 1; continue; }

  const titleCn = String(parsed.translation || '');
  const summary = String(parsed.summary || '');
  const sentiment = String(parsed.sentiment || '');

  if (summary === BLOCKED) { bump(bucket, 'blocked'); totals.blocked += 1; continue; }

  if (!TAGS.some((t) => titleCn.startsWith('[' + t + '] '))) {
    bump(bucket, 'tag_invalid'); totals.tag_invalid += 1;
  }
  if (summary.length > 200) { bump(bucket, 'too_long'); totals.too_long += 1; }
  if (!summary || END_PUNCT.indexOf(summary.slice(-1)) === -1) {
    bump(bucket, 'no_end_punct'); totals.no_end_punct += 1;
  }
  if (summary.indexOf('"') !== -1 || summary.indexOf("'") !== -1) {
    bump(bucket, 'ascii_quote'); totals.ascii_quote += 1;
  }
  if (SENTIMENTS.indexOf(sentiment) === -1) {
    bump(bucket, 'sentiment_invalid'); totals.sentiment_invalid += 1;
  }
}

const pct = (n) => (totals.n ? (n / totals.n * 100).toFixed(1) + '%' : 'n/a');
const line = 'n=' + totals.n
  + ' unparseable=' + totals.unparseable + '(' + pct(totals.unparseable) + ')'
  + ' tag_invalid=' + totals.tag_invalid + '(' + pct(totals.tag_invalid) + ')'
  + ' too_long=' + totals.too_long + '(' + pct(totals.too_long) + ')'
  + ' no_end_punct=' + totals.no_end_punct + '(' + pct(totals.no_end_punct) + ')'
  + ' ascii_quote=' + totals.ascii_quote + '(' + pct(totals.ascii_quote) + ')'
  + ' sentiment_invalid=' + totals.sentiment_invalid + '(' + pct(totals.sentiment_invalid) + ')'
  + ' blocked=' + totals.blocked;

return [{ json: { totals: totals, by_source: bySource, summary_line: line } }];
